const listCaseRows = `-- name: ListCaseRows :many
SELECT k.id, k.customer_id, k.bank_id, k.loan_amount, k.tracking_number, k.current_stage_id,
       k.assignee_id, k.status, k.created_at, k.follow_up_date, k.project_id, k.lead_id, k.unit_number, k.builder_contact_id,
       cu.name AS customer_name, cu.mobile AS customer_mobile, b.name AS bank_name, p.name AS project_name,
       s.name AS stage_name, s.code AS stage_code, COALESCE(s.role, '')::text AS stage_role,
       (SELECT count(*) FROM stages x
         WHERE x.is_active AND x.bank_id IS NOT DISTINCT FROM s.bank_id AND x.sort_order <= s.sort_order)::int AS stage_order,
       (SELECT count(*) FROM stages x
         WHERE x.is_active
           AND x.bank_id IS NOT DISTINCT FROM
               (CASE WHEN EXISTS (SELECT 1 FROM stages y WHERE y.bank_id = k.bank_id AND y.is_active)
                     THEN k.bank_id END))::int AS stage_count,
       u.full_name AS assignee_name,
       COALESCE((SELECT max(e.reached_at) FROM case_stage_events e
                  WHERE e.case_id = k.id AND e.stage_id = k.current_stage_id), k.created_at)::timestamptz AS stage_since,
       (s.requires_document AND NOT EXISTS (SELECT 1 FROM documents d WHERE d.case_id = k.id))::boolean AS needs_document
FROM cases k
JOIN customers cu ON cu.id = k.customer_id
JOIN banks b ON b.id = k.bank_id
JOIN projects p ON p.id = k.project_id
JOIN stages s ON s.id = k.current_stage_id
JOIN users u ON u.id = k.assignee_id
WHERE ($1::bigint IS NULL OR k.current_stage_id = $1::bigint)
  AND ($2::bigint IS NULL OR k.bank_id = $2::bigint)
  AND ($3::bigint IS NULL OR k.project_id = $3::bigint)
  AND ($4::bigint IS NULL OR k.assignee_id = $4::bigint)
  AND ($5::timestamptz IS NULL OR k.created_at >= $5::timestamptz)
  AND ($6::timestamptz IS NULL OR k.created_at < $6::timestamptz)
  AND ($7::bigint IS NULL OR k.customer_id = $7::bigint)
ORDER BY k.created_at DESC, k.id DESC
`

type ListCaseRowsParams struct {
	StageID    pgtype.Int8
	BankID     pgtype.Int8
	ProjectID  pgtype.Int8
	AssigneeID pgtype.Int8
	FromTs     pgtype.Timestamptz
	ToTs       pgtype.Timestamptz
	CustomerID pgtype.Int8
}

type ListCaseRowsRow struct {
	ID               int64
	CustomerID       int64
	BankID           int64
	LoanAmount       pgtype.Numeric
	TrackingNumber   pgtype.Text
	CurrentStageID   int64
	AssigneeID       int64
	Status           string
	CreatedAt        pgtype.Timestamptz
	FollowUpDate     pgtype.Date
	ProjectID        int64
	LeadID           pgtype.Int8
	UnitNumber       pgtype.Text
	BuilderContactID pgtype.Int8
	CustomerName     string
	CustomerMobile   string
	BankName         string
	ProjectName      string
	StageName        string
	StageCode        string
	StageRole        string
	StageOrder       int32
	StageCount       int32
	AssigneeName     string
	StageSince       pgtype.Timestamptz
	NeedsDocument    bool
}

// ListCases plus the names and stage progress the case list shows.
// stage_count uses the bank's own stages when it has any, else the standard stages.
func (q *Queries) ListCaseRows(ctx context.Context, arg ListCaseRowsParams) ([]ListCaseRowsRow, error) {
	rows, err := q.db.Query(ctx, listCaseRows,
		arg.StageID,
		arg.BankID,
		arg.ProjectID,
		arg.AssigneeID,
		arg.FromTs,
		arg.ToTs,
		arg.CustomerID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListCaseRowsRow
	for rows.Next() {
		var i ListCaseRowsRow
		if err := rows.Scan(
			&i.ID,
			&i.CustomerID,
			&i.BankID,
			&i.LoanAmount,
			&i.TrackingNumber,
			&i.CurrentStageID,
			&i.AssigneeID,
			&i.Status,
			&i.CreatedAt,
			&i.FollowUpDate,
			&i.ProjectID,
			&i.LeadID,
			&i.UnitNumber,
			&i.BuilderContactID,
			&i.CustomerName,
			&i.CustomerMobile,
			&i.BankName,
			&i.ProjectName,
			&i.StageName,
			&i.StageCode,
			&i.StageRole,
			&i.StageOrder,
			&i.StageCount,
			&i.AssigneeName,
			&i.StageSince,
			&i.NeedsDocument,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

