const searchCustomerIDs = `-- name: SearchCustomerIDs :many
SELECT DISTINCT c.id, c.name FROM customers c
LEFT JOIN cases k ON k.customer_id = c.id
LEFT JOIN banks b ON b.id = k.bank_id
LEFT JOIN projects p ON p.id = k.project_id
WHERE c.name ILIKE $1
   OR c.mobile = $2
   OR k.tracking_number = $3
   OR b.name ILIKE $1
   -- NA is never matched: most cases are NA and "na" is in many names.
   OR (p.name ILIKE $1 AND NOT p.is_system)
ORDER BY c.name, c.id
`

type SearchCustomerIDsParams struct {
	NamePattern string
	Mobile      string
	Tracking    pgtype.Text
}

